// Generated by Viscosity: "es" stored as a struct of arrays (fields id, hp, x, tag).
class __Vsc_es {
  constructor(cap = 16) { this.length = 0; this.cap = cap; this.hp = new Float64Array(cap); this.x = new Float64Array(cap); this.id = []; this.tag = []; }
  static of(...v) { const c = new __Vsc_es(Math.max(16, v.length / 4)); for (let i = 0; i < v.length; i += 4) c.push(v[i + 0], v[i + 1], v[i + 2], v[i + 3]); return c; }
  push(v0, v1, v2, v3) { const n = this.length; if (n === this.cap) this.grow(); this.id[n] = v0; this.hp[n] = v1; this.x[n] = v2; this.tag[n] = v3; return (this.length = n + 1); }
  grow() { const cap = (this.cap *= 2); let t; t = new Float64Array(cap); t.set(this.hp); this.hp = t; t = new Float64Array(cap); t.set(this.x); this.x = t; }
}
// viscosity: es=soa
const es = new __Vsc_es();
for (let i = 0; i < 300; i++) es.push('e' + i, 100, i, i % 3 ? null : { boss: true });
for (let r = 0; r < 3; r++) {
  for (let i = 0; i < es.length; i++) {
    es.x[i] += 1;
    if (es.tag[i] !== null) es.hp[i] -= 10;
  }
}
es.id[4] = 42;
let s = 0;
for (let e = 0; e < es.length; e++) s += es.hp[e] + es.x[e];
console.log(s, es.id[3], es.id[4], es.tag[3].boss, es.tag[5]);
